import{_ as t,o as a,c as d,a2 as i}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"Configuration fields","description":"","frontmatter":{},"headers":[],"relativePath":"reference/configuration.md","filePath":"reference/configuration.md"}'),o={name:"reference/configuration.md"};function r(n,e,l,s,c,h){return a(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="configuration-fields" tabindex="-1">Configuration fields <a class="header-anchor" href="#configuration-fields" aria-label="Permalink to &quot;Configuration fields&quot;">​</a></h1><p>The configuration is a JSON object in <code>kittyscape.json</code>, in kitty’s active configuration directory. It is user-owned data. No visited repository is searched for configuration.</p><h2 id="top-level-fields" tabindex="-1">Top-level fields <a class="header-anchor" href="#top-level-fields" aria-label="Permalink to &quot;Top-level fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>version</code></td><td>Integer</td><td>Required</td><td>Schema version. This build uses <code>1</code>.</td></tr><tr><td><code>enabled</code></td><td>Boolean</td><td><code>true</code></td><td>Enable automatic directory selection.</td></tr><tr><td><code>rules</code></td><td>Array</td><td><code>[]</code></td><td>Directory/image mappings. An empty array is valid.</td></tr><tr><td><code>fallback</code></td><td>String or <code>null</code></td><td><code>null</code></td><td>Local image used when no rule matches; omission or <code>null</code> selects baseline restoration.</td></tr></tbody></table><p>Unknown fields, repeated JSON fields, unsupported versions, wrong types, and duplicate normalized roots are validation errors. The UTF-8 JSON file must be a regular file at most 1 MiB, with at most 10,000 rules. Invalid reloads retain the last valid configuration.</p><h2 id="rule-fields" tabindex="-1">Rule fields <a class="header-anchor" href="#rule-fields" aria-label="Permalink to &quot;Rule fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>directory</code></td><td>String</td><td>Existing absolute directory root, or a path beginning with the user’s <code>~/</code> home shortcut.</td></tr><tr><td><code>image</code></td><td>String</td><td>Local PNG path; relative values resolve beside the configuration file.</td></tr></tbody></table><p>The deepest component ancestor wins. Symlinked roots and reported directories are physically normalized. A sibling that merely starts with the same characters does not match. For a symlinked JSON file, relative images still resolve beside the selected configuration path, not beside the symlink target.</p><h2 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to &quot;Images&quot;">​</a></h2><p>Rule and fallback images must be local static PNGs. HTTP URLs, executable providers, and automatic downloads are outside this build. The image must be a readable local file. A missing, invalid, or oversized image uses the fallback policy and a bounded diagnostic instead of interrupting the shell.</p><table tabindex="0"><thead><tr><th>Limit</th><th>Maximum</th></tr></thead><tbody><tr><td>Encoded file size</td><td>16 MiB</td></tr><tr><td>Width or height</td><td>4,096 pixels each</td></tr><tr><td>Pixel count</td><td>16,000,000 pixels</td></tr><tr><td>Decoded image data</td><td>64 MiB</td></tr></tbody></table><p>Only static PNGs are accepted. The shared image cache is bounded to 32 MiB. The <a href="./../development/compatibility-findings.html">runtime findings</a> distinguish validation tests from measured decoding and display performance.</p><h2 id="path-examples" tabindex="-1">Path examples <a class="header-anchor" href="#path-examples" aria-label="Permalink to &quot;Path examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Value</th><th>Interpretation</th></tr></thead><tbody><tr><td><code>~/Projects/Little Garden</code></td><td>Home-relative shortcut expanded to a physical absolute directory root.</td></tr><tr><td><code>/example/Projects/app</code></td><td>Matches this directory and descendants, never <code>/example/Projects/application</code>.</td></tr><tr><td><code>images/quiet.png</code></td><td>Image beside the JSON file under <code>images/</code>.</td></tr><tr><td><code>$(command)/image.png</code></td><td>No shell evaluation; command interpolation is not supported.</td></tr></tbody></table><p>The <a href="./../guide/configuration.html">configuration guide</a> includes a complete two-rule example and exit-to-default behavior.</p>',15)])])}const p=t(o,[["render",r]]);export{m as __pageData,p as default};
